// En Java no hay método nativo para dividir un array en N partes.
// Tienes que usar Arrays.copyOfRange() manualmente en un bucle.
int[] arr = {1, 2, 3, 4, 5, 6};
int[][] nuevos = new int[3][2];

for(int i=0; i<3; i++) {
    nuevos[i] = java.util.Arrays.copyOfRange(arr, i*2, i*2 + 2);
}
